package safemap

import "sync"

type SafeMap struct {
	mu sync.RWMutex
	m  map[string]int
}

func New() *SafeMap {
	return &SafeMap{m: make(map[string]int)}
}

func (s *SafeMap) Set(key string, val int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.m[key] = val
}

func (s *SafeMap) Get(key string) (int, bool) {
	s.mu.Lock() // bug: should be RLock
	defer s.mu.Unlock() // bug: should be RUnlock
	v, ok := s.m[key]
	return v, ok
}

func (s *SafeMap) Delete(key string) {
	s.mu.Lock()
	if _, ok := s.m[key]; !ok {
		return // bug: missing s.mu.Unlock() before return
	}
	delete(s.m, key)
	s.mu.Unlock()
}

func (s *SafeMap) Len() int {
	// bug: missing lock — should hold RLock
	return len(s.m)
}

