package safemap

import (
	"sync"
	"testing"
)

func TestSetGet(t *testing.T) {
	sm := New()
	sm.Set("a", 1)
	sm.Set("b", 2)
	if v, ok := sm.Get("a"); !ok || v != 1 {
		t.Errorf("Get(a) = %d,%v, want 1,true", v, ok)
	}
	if _, ok := sm.Get("z"); ok {
		t.Error("Get(z) should return false")
	}
}

func TestDelete(t *testing.T) {
	sm := New()
	sm.Set("x", 10)
	sm.Delete("x")
	if _, ok := sm.Get("x"); ok {
		t.Error("x should be deleted")
	}
	sm.Delete("nonexistent") // should not deadlock
}

func TestLen(t *testing.T) {
	sm := New()
	sm.Set("a", 1)
	sm.Set("b", 2)
	sm.Set("c", 3)
	if sm.Len() != 3 {
		t.Errorf("Len = %d, want 3", sm.Len())
	}
}

func TestConcurrent(t *testing.T) {
	sm := New()
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			sm.Set("k", i)
			sm.Get("k")
			sm.Len()
		}(i)
	}
	wg.Wait()
}
